class Wallet:
    def __init__(self, owner):
        self.owner = owner
        self.balance = 0
        self.history = []

    def _record(self, kind, amount):
        self.history.append((kind, amount))

    def add_money(self, amount):
        self.balance += amount
        self._record("added", amount)

