class Product:
    def __init__(self, name, price, stock):
        self.name = name
        self.price = price
        self.stock = stock

    def restock(self, qty):
        self.stock += qty

    def sell(self, qty):
        if qty > self.stock:
            raise ValueError("Not enough stock")
        self.stock -= qty
        return self.price * qty


tea = Product("Assam Tea 250g", 180, 10)
print(tea.sell(3), tea.stock)

